const n=Number($json.followup_count||0)+1;
const product=$json.product_name || 'পণ্যটি';
const reply=n===1
 ? `আপনি যে ${product} সম্পর্কে জানতে চেয়েছিলেন, সেটি নিয়ে কি আর কোনো তথ্য জানতে চান? চাইলে আমি অর্ডার করতেও সাহায্য করতে পারি।`
 : `আপনি কি এখনও ${product} অর্ডার করতে আগ্রহী? প্রয়োজন হলে আমি অর্ডারটি সম্পন্ন করতে সাহায্য করতে পারি।`;
return [{json:{...$json,reply,followupNo:n}}];
